#ifndef MEP_FISH_LSP_H
#define MEP_FISH_LSP_H

// The analysis half of mep's own Fish language server (the wire half is
// fish_lsp_server.cpp, the `mep-fish-lsp` binary; the `fish_ls` entry
// in main.cpp's kBuiltinLsp spawns it). Everything here is a pure function
// of the document text, so the whole server is testable without a client
// (fish_lsp_test.cpp). Positions are 0-based lines and 0-based byte
// columns (`positionEncoding: "utf-8"`).
//
// Generated by tools/new_language.py; nix_lsp.h is the worked example of
// every function below.

#include <memory>
#include <string>
#include <vector>

struct FishLspRange {
    int line = 0, col = 0, end_line = 0, end_col = 0;
};

class FishLspDocument;

/** @brief Parses and analyses a document; every query below runs on the result. */
std::shared_ptr<const FishLspDocument> FishLspAnalyze(const std::vector<std::string> &lines);

// --- Diagnostics ------------------------------------------------------------------

enum class FishLspSeverity { Error = 1, Warning = 2, Information = 3, Hint = 4 };

struct FishLspDiagnostic {
    FishLspRange range;
    FishLspSeverity severity = FishLspSeverity::Error;
    std::string code;  // stable id: syntax-error, ...
    std::string message;
    bool unnecessary = false;  // LSP DiagnosticTag.Unnecessary
    bool deprecated = false;   // LSP DiagnosticTag.Deprecated
};

std::vector<FishLspDiagnostic> FishLspDiagnostics(const FishLspDocument &doc);
/** @brief fish's own verdict on @p text: "" when `fish --no-execute` accepts it, else its first
 *  error as `PATH (line N): message` (or `PATH: message` at the end of the input). */
std::string FishLspFishCheck(const std::string &text, const std::string &path);
/** @brief `path:line:col: severity: message [code]`, 1-based, as `--lint` prints it. */
std::string FishLspFormatDiagnostic(const std::string &path, const FishLspDiagnostic &d);
/** @brief Whether a diagnostic makes `--lint` exit non-zero (an error or a warning). */
bool FishLspDiagnosticFails(const FishLspDiagnostic &d);

// --- Completion / hover / signature help -------------------------------------------

enum class FishLspKind {
    Text = 1, Method = 2, Function = 3, Field = 5, Variable = 6, Class = 7, Module = 9, Property = 10,
    Value = 12, Keyword = 14, Snippet = 15, Constant = 21, Struct = 22,
};

struct FishLspCompletionItem {
    std::string label;
    std::string insert_text;
    FishLspKind kind = FishLspKind::Text;
    std::string detail;
    std::string documentation;
    int replace_start = 0, replace_end = 0;  // byte columns on the request's line
};

std::vector<FishLspCompletionItem> FishLspCompletions(const FishLspDocument &doc, int line, int col);

struct FishLspHoverInfo {
    bool found = false;
    std::string text;  // markdown
    FishLspRange range;
};

FishLspHoverInfo FishLspHover(const FishLspDocument &doc, int line, int col);

struct FishLspSignatureHelp {
    bool found = false;
    std::string label;
    std::vector<std::string> params;  // substrings of label
    std::string documentation;
    int active_param = 0;
};

FishLspSignatureHelp FishLspSignatureAt(const FishLspDocument &doc, int line, int col);

// --- Navigation -------------------------------------------------------------------------

struct FishLspLocation {
    FishLspRange range;
};

std::vector<FishLspLocation> FishLspDefinition(const FishLspDocument &doc, int line, int col);

struct FishLspReference {
    FishLspRange range;
    bool is_definition = false;
};

std::vector<FishLspReference> FishLspReferences(const FishLspDocument &doc, int line, int col);

struct FishLspTextEdit {
    FishLspRange range;
    std::string new_text;
};

struct FishLspRenameTarget {
    bool found = false;
    FishLspRange range;
    std::string placeholder;
};

FishLspRenameTarget FishLspPrepareRename(const FishLspDocument &doc, int line, int col);
std::vector<FishLspTextEdit> FishLspRename(const FishLspDocument &doc, int line, int col,
                                               const std::string &new_name, std::string *error);

// --- Outline / folding --------------------------------------------------------------------

enum class FishLspSymbolKind {
    File = 1, Module = 2, Namespace = 3, Class = 5, Method = 6, Property = 7, Field = 8, Function = 12,
    Variable = 13, Constant = 14, String = 15, Number = 16, Boolean = 17, Array = 18, Object = 19, Key = 20,
    Null = 21,
};

struct FishLspSymbol {
    std::string name;
    std::string detail;
    FishLspSymbolKind kind = FishLspSymbolKind::Variable;
    FishLspRange range;
    FishLspRange sel_range;
    int parent = -1;
};

std::vector<FishLspSymbol> FishLspSymbols(const FishLspDocument &doc);

struct FishLspFold {
    int start_line = 0, end_line = 0;
    std::string kind;  // "" or "comment"
};

std::vector<FishLspFold> FishLspFolds(const FishLspDocument &doc);

// --- Formatting ------------------------------------------------------------------------------

/** @brief The formatter as one edit over the changed lines; none when already formatted. */
std::vector<FishLspTextEdit> FishLspFormat(const std::vector<std::string> &lines, int width, std::string *error);

#endif  // MEP_FISH_LSP_H
